// Spawn food
function spawnFood() {
  let pos;
  do {
    pos = {
      x: Math.floor(Math.random() * GRID_SIZE),
      y: Math.floor(Math.random() * GRID_SIZE)
    };
  } while (
    snakes.some(snake => snake.alive &&
      snake.body.some(seg => seg.x === pos.x && seg.y === pos.y))
  );
  food = pos;
}

// Draw food
function drawFood() {
  if (!food) return;
  const cell = grid.children[food.x * GRID_SIZE + food.y + 1];
  if (cell) {
    cell.style.background = '#ff6b6b';
  }
}

// Update grid display
function updateGrid() {
  for (let i = 0; i < GRID_SIZE * GRID_SIZE; i++) {
    const cell = grid.children[i + 1];
    cell.style.background = '#16213e';
  }
  drawFood();
  snakes.forEach(snake => snake.draw());
}

// Game over
function gameOver() {
  gameRunning = false;
  if (gameLoop) clearInterval(gameLoop);
  finalScoreEl.textContent = score;
  gameOver.style.display = 'block';
}

// Restart
function restartGame() {
  snakes = [new Snake(false), new Snake(true)];
  score = 0;
  scoreEl.textContent = '0';
  spawnFood();
  gameRunning = true;
  menu.style.display = 'none';
  gameOver.style.display = 'none';
